begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table ids(k text primary key,id uuid);
grant all on ids to authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000102","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*) from public.clients),1::bigint,'lawyer reads only own clients');
select is((select count(*) from public.matters),1::bigint,'lawyer reads all own-firm matters, including another responsible');
select is((select count(*) from public.firm_team('10000000-0000-4000-a000-000000000001')),2::bigint,'assignment includes active coworkers only');
select throws_ok($$select * from public.firm_team('10000000-0000-4000-a000-000000000002')$$,'42501',null::text,'no cross-firm team enumeration');
select throws_ok($$insert into public.clients(firm_id,name,channel) values('10000000-0000-4000-a000-000000000001','Bypass','PHONE')$$,'42501',null::text,'direct writes cannot bypass use cases');
select throws_ok($$select public.save_client('10000000-0000-4000-a000-000000000002','Wrong','','','PHONE')$$,'42501',null::text,'supplied other firm is rejected');
select throws_ok($$select public.create_matter('10000000-0000-4000-a000-000000000001','30000000-0000-4000-a000-000000000002','20000000-0000-4000-a000-000000000101','Wrong','')$$,'23503',null::text,'client FK cannot cross firms');
select throws_ok($$select public.create_matter('10000000-0000-4000-a000-000000000001','30000000-0000-4000-a000-000000000001','20000000-0000-4000-a000-000000000201','Wrong','')$$,'23514',null::text,'responsible cannot belong to other firm');
select throws_ok($$select public.create_matter('10000000-0000-4000-a000-000000000001','30000000-0000-4000-a000-000000000001','20000000-0000-4000-a000-000000000103','Wrong','')$$,'23514',null::text,'inactive responsible rejected');
insert into ids values('client',public.save_client('10000000-0000-4000-a000-000000000001','Prueba SQL','','','REFERRAL'));
select is(public.save_client('10000000-0000-4000-a000-000000000001','Prueba editada','','555','REFERRAL',(select id from ids where k='client')),(select id from ids where k='client'),'edit preserves client identity');
insert into ids values('matter',public.create_matter('10000000-0000-4000-a000-000000000001',(select id from ids where k='client'),'20000000-0000-4000-a000-000000000102','Asunto SQL',''));
insert into ids values('event',public.add_event('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),'Audiencia SQL','HEARING',now()-interval '2 days',''));
select lives_ok($$select public.reschedule_event('10000000-0000-4000-a000-000000000001',(select id from ids where k='event'),now()-interval '1 day','Cambio de sede',1)$$,'rescheduling succeeds');
select is((select count(*) from public.event_changes where event_id=(select id from ids where k='event')),1::bigint,'original schedule preserved');
select throws_ok($$select public.reschedule_event('10000000-0000-4000-a000-000000000001',(select id from ids where k='event'),now(),'Stale screen',1)$$,'40001',null::text,'stale reschedule rejected');
select is((select version from public.events where id=(select id from ids where k='event')),2,'stale operation does not increment version');
select throws_ok($$select public.record_movement('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),now(),'Notes',(select id from ids where k='event'),'',current_date)$$,'23514',null::text,'invalid next task rolls entire outcome back');
select is((select status from public.events where id=(select id from ids where k='event')),'SCHEDULED','failed outcome does not close event');
select is((select count(*) from public.movements),0::bigint,'failed outcome leaves no movement');
select throws_ok($$select public.record_movement('10000000-0000-4000-a000-000000000001','40000000-0000-4000-a000-000000000001',now(),'Wrong matter',(select id from ids where k='event'))$$,'40001',null::text,'event cannot attach to a different matter');
select throws_ok($$select public.record_movement('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),now()+interval '1 day','Future')$$,'23514',null::text,'future event is not an occurrence');
insert into ids values('movement',public.record_movement('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),now(),'Resultado confidencial',(select id from ids where k='event'),'Preparar escrito',current_date+2));
select is((select status from public.events where id=(select id from ids where k='event')),'RECORDED','successful outcome closes linked event');
select is((select count(*) from public.tasks where matter_id=(select id from ids where k='matter')),1::bigint,'next task created atomically');
select throws_ok($$select public.record_movement('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),now(),'Duplicate',(select id from ids where k='event'))$$,'40001',null::text,'double submission cannot duplicate linked result');
insert into ids values('document',public.reserve_document('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),'example.pdf','application/pdf',20));
select throws_ok($$select public.finish_document('10000000-0000-4000-a000-000000000001',(select id from ids where k='document'))$$,'23514',null::text,'metadata alone cannot claim complete upload');
select lives_ok($$select public.cancel_document('10000000-0000-4000-a000-000000000001',(select id from ids where k='document'))$$,'interrupted upload can be discarded');
select throws_ok($$select public.finish_document('10000000-0000-4000-a000-000000000001',(select id from ids where k='document'))$$,'55000',null::text,'discarded upload cannot be finalized');
select lives_ok($$select public.set_matter_archived('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),true)$$,'lawyer can archive own-firm matter');
select throws_ok($$select public.add_task('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),'Blocked',current_date)$$,'55000',null::text,'archive blocks new work');
select is((select count(*) from public.movements),1::bigint,'archive preserves history');
select lives_ok($$select public.set_matter_archived('10000000-0000-4000-a000-000000000001',(select id from ids where k='matter'),false)$$,'reopening preserves identity');
select throws_ok('delete from public.movements','42501',null::text,'lawyer cannot delete history');
reset role;
select is((select count(*) from public.audit_logs where metadata::text like '%Resultado confidencial%'),0::bigint,'audit omits confidential notes');
update public.firm_memberships set status='INACTIVE' where profile_id='00000000-0000-4000-a000-000000000102';
set local role authenticated;
select is((select count(*) from public.clients),0::bigint,'same JWT loses access after membership revocation');
select throws_ok($$select public.save_client('10000000-0000-4000-a000-000000000001','Revoked','','','PHONE')$$,'42501',null::text,'revocation blocks RPC writes');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000201","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*) from public.clients),1::bigint,'firm B cannot read newly created A clients');
select is((select count(*) from public.movements),0::bigint,'firm B cannot read A history');
select is((select count(*) from public.documents),0::bigint,'firm B cannot read A document metadata');
select throws_ok($$select public.set_matter_archived('10000000-0000-4000-a000-000000000001','40000000-0000-4000-a000-000000000001',true)$$,'42501',null::text,'firm B cannot archive A matters');
reset role;
select * from finish();
rollback;
